import { displayTitle } from '@sanity/workflow-engine';
function withNotes(text, ...notes) {
    const present = notes.filter((note) => note !== undefined);
    return present.length === 0 ? text : `${text} (${present.join(': ')})`;
}
function withMoveNotes(text, { via, reason }) {
    return withNotes(text, via === 'setStage' ? 'forced' : undefined, reason);
}
function transitionName(move) {
    return move.via === 'setStage' || move.transition === undefined ? '' : `${move.transition}, `;
}
const detailOf = {
    stageEntered: (entry) => withMoveNotes(entry.stage, entry),
    stageExited: (entry) => entry.stage,
    activityStatusChanged: (entry) => `${entry.activity} ${entry.from} → ${entry.to}`,
    actionFired: (entry) => withNotes(`${entry.activity} → ${entry.action}`, entry.triggered ? 'triggered' : undefined),
    transitionFired: (entry) => withMoveNotes(`${transitionName(entry)}${entry.fromStage} → ${entry.toStage}`, entry),
    effectQueued: (entry) => entry.effect,
    effectCompleted: (entry) => withNotes(entry.effect, entry.status, entry.detail),
    effectClaimReleased: (entry) => entry.effect,
    spawned: (entry) => `${entry.activity} → ${entry.instanceRef.id}`,
    subworkflowAdopted: (entry) => `${entry.activity} → ${entry.instanceRef.id}`,
    subworkflowResolved: (entry) => withNotes(entry.activity, entry.status),
    subworkflowOrphaned: (entry) => entry.instanceRef.id,
    aborted: (entry) => entry.reason,
    opApplied: (entry) => {
        const subject = entry.target?.field ?? entry.activity;
        return subject === undefined ? entry.opType : `${entry.opType} ${subject}`;
    },
    fieldQueryDiscarded: (entry) => entry.field,
};
function actorOf(entry) {
    if (entry._type === 'actionFired' && entry.triggered) {
        return undefined;
    }
    return 'actor' in entry ? entry.actor : undefined;
}
export function historyRow(entry) {
    const detail = detailOf[entry._type](entry);
    const actor = actorOf(entry);
    const title = displayTitle(entry._type);
    const described = detail === undefined ? title : `${title}: ${detail}`;
    return actor === undefined ? described : `${described} (by ${actor.id})`;
}
